Let \(X_1,\ldots,X_N\) be i.i.d. copies of a centered sub-Gaussian random
vector \(X\in\mathbb R^d\) with covariance matrix \(\Sigma\) and
sub-Gaussian constant \(K\). Let \(p\ge2\) be an integer. Then, for every
\(q\ge1\),
\begin{equation}
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\|
\bigg(
\sum_{i=1}^N
\big\|
X_i^{\otimes p}-\mathbb{E} X^{\otimes p}
\big\|_{\mathsf F}^2
\bigg)^{1/2}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\|_{L_q}
\lesssim_p
K^p
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(
\sqrt N\,\mathrm{Tr}(\Sigma)^{p/2}
+
\|\Sigma\|^{p/2}q^{p/2}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right).
\end{equation}
Moreover, if \(X\) is Gaussian, then
\begin{equation}
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\|
\bigg(
\sum_{i=1}^N
\big\|
X_i^{\otimes p}-\mathbb{E} X^{\otimes p}
\big\|_{\mathsf F}^2
\bigg)^{1/2}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\|_{L_q}
\asymp_p
\sqrt N\,\mathrm{Tr}(\Sigma)^{p/2}
+
\|\Sigma\|^{p/2}q^{p/2}.
\end{equation}

Let \(X_1,\ldots,X_N\) be i.i.d. copies of a centered sub-Gaussian random
vector \(X\in\mathbb R^d\) with covariance matrix \(\Sigma\) and
sub-Gaussian constant \(K\). Let \(p\ge2\) be an integer. Then, for every
\(q\ge1\),
\begin{align}
\sup_{\|A\|_{\mathsf F}\le1}\bigg\|
\sum_{i=1}^N
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\langle
A,X_i^{\otimes p}-\mathbb{E} X^{\otimes p}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\rangle_{\mathsf F}
\bigg\|_{L_q}
\lesssim_p K^p
\begin{cases}
\rho_p(\Sigma)\sqrt{N(q\land N)}
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ even},\\[3pt]
\rho_p(\Sigma)\sqrt{Nq}
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ odd},
\end{cases}

\end{align}
where \(\rho_p(\Sigma)\) is as in Theorem~2.1. Moreover, if \(X\) is Gaussian, then
\begin{align}
\sup_{\|A\|_{\mathsf F}\le1}\bigg\|
\sum_{i=1}^N
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\langle
A,X_i^{\otimes p}-\mathbb{E} X^{\otimes p}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\rangle_{\mathsf F}
\bigg\|_{L_q}
\asymp_p
\begin{cases}
\rho_{p,G}(\Sigma)\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\sqrt{Nq}+q\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ even},\\[3pt]
\rho_{p,G}(\Sigma)\sqrt{Nq}
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ odd},
\end{cases}

\end{align}
where \(\rho_{p,G}(\Sigma)\) is as in Theorem~2.1.

Let \(Y_1,\ldots,Y_N\) be independent copies of a centered real-valued
random variable \(Y\). Then, for every \(q\ge2\) such that \(Y\in L_q\),
\begin{equation}
\bigg\|
\sum_{i=1}^N Y_i
\bigg\|_{L_q}
\asymp
\sup_{\max\{2,q/N\}\le s\le q}
\frac qs
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac Nq\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)^{1/s}
\|Y\|_{L_s}.
\end{equation}

Let \(X\in\mathbb R^d\) be a centered sub-Gaussian random vector with
covariance matrix \(\Sigma\) and sub-Gaussian constant \(K\), and let
\(p\ge2\) be an integer. Then, for every \(q\ge1\),
\[
\sup_{\|A\|_{\mathsf F}=1}
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\|
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\langle
A,X^{\otimes p}-\mathbb{E} X^{\otimes p}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\rangle_{\mathsf F}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\|_{L_q}
\lesssim_p
K^p \begin{cases}
\|\Sigma\|_{\mathsf F}^{p/2}+\|\Sigma\|^{p/2}q^{p/2},
& p \text{ even},\\[3pt]
\|\Sigma\|_{\mathsf F}^{(p-1)/2}\|\Sigma\|^{1/2}\sqrt q+\|\Sigma\|^{p/2}q^{p/2},
& p \text{ odd}.
\end{cases}
\]
 Moreover, if \(X\) is Gaussian, then, for every \(q\ge1\),
\[
\sup_{\|A\|_{\mathsf F}=1}
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\|
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\langle
A,X^{\otimes p}-\mathbb{E} X^{\otimes p}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\rangle_{\mathsf F}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\|_{L_q}
\asymp_p
\begin{cases}
\|\Sigma\|_{\mathsf F}^{p/2-1}\|\Sigma\| q
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ even},\\[3pt]
\|\Sigma\|_{\mathsf F}^{(p-1)/2}\|\Sigma\|^{1/2}\sqrt q
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ odd},
\end{cases}
\]
and 
\[
\sup_{\|A\|_{\mathsf F}=1}
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\|
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\langle
A,X^{\otimes p}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\rangle_{\mathsf F}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\|_{L_q}
\asymp_p
\begin{cases}
\|\Sigma\|_{\mathsf F}^{p/2}
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ even},\\[3pt]
\|\Sigma\|_{\mathsf F}^{(p-1)/2}\|\Sigma\|^{1/2}\sqrt q
+
\|\Sigma\|^{p/2}q^{p/2},
& p \text{ odd}.
\end{cases}
\]
